-- ==============================================================================
-- HEALTHCARE DATA ANALYTICS: SQL BUSINESS & CLINICAL QUERIES
-- Dataset: Healthcare Inpatient Admissions & Clinical Operations (55,500 records)
-- Database Engine: PostgreSQL / ANSI SQL Compatible
-- Table: healthcare
-- ==============================================================================

-- Q1. What is the total billing amount and average cost generated by male vs female patients?
SELECT 
    gender, 
    COUNT(*) AS total_patients,
    ROUND(SUM(billing_amount)::numeric, 2) AS total_billing_revenue,
    ROUND(AVG(billing_amount)::numeric, 2) AS average_billing
FROM healthcare
GROUP BY gender
ORDER BY total_billing_revenue DESC;


-- Q2. Which patients had Emergency admissions but still incurred billing higher than the overall average billing amount?
SELECT 
    name, 
    medical_condition, 
    admission_type, 
    billing_amount
FROM healthcare
WHERE admission_type = 'Emergency' 
  AND billing_amount >= (SELECT AVG(billing_amount) FROM healthcare)
ORDER BY billing_amount DESC
LIMIT 10;


-- Q3. Which medical conditions have the highest average length of stay and average billing amount?
SELECT 
    medical_condition,
    COUNT(*) AS total_cases,
    ROUND(AVG(length_of_stay)::numeric, 2) AS avg_length_of_stay_days,
    ROUND(AVG(billing_amount)::numeric, 2) AS avg_billing_amount
FROM healthcare
GROUP BY medical_condition
ORDER BY avg_length_of_stay_days DESC;


-- Q4. Compare the average billing amount and length of stay between Emergency and Urgent admissions.
SELECT 
    admission_type,
    COUNT(*) AS total_admissions,
    ROUND(AVG(billing_amount)::numeric, 2) AS avg_billing_amount,
    ROUND(AVG(length_of_stay)::numeric, 2) AS avg_length_of_stay_days
FROM healthcare
WHERE admission_type IN ('Emergency', 'Urgent')
GROUP BY admission_type;


-- Q5. Compare patient volume, average billing, and total revenue across different Insurance Providers.
SELECT 
    insurance_provider,
    COUNT(*) AS total_patients,
    ROUND(AVG(billing_amount)::numeric, 2) AS avg_billing,
    ROUND(SUM(billing_amount)::numeric, 2) AS total_revenue
FROM healthcare
GROUP BY insurance_provider
ORDER BY total_revenue DESC, avg_billing DESC;


-- Q6. Which medical conditions have the highest percentage of 'Abnormal' test results?
SELECT 
    medical_condition,
    COUNT(*) AS total_cases,
    SUM(CASE WHEN test_results = 'Abnormal' THEN 1 ELSE 0 END) AS abnormal_cases,
    ROUND(100.0 * SUM(CASE WHEN test_results = 'Abnormal' THEN 1 ELSE 0 END) / COUNT(*), 2) AS abnormal_rate_percentage
FROM healthcare
GROUP BY medical_condition
ORDER BY abnormal_rate_percentage DESC;


-- Q7. Segment patients into Short Stay (1-7 days), Medium Stay (8-21 days), and Extended Stay (>21 days), and show patient count & financial metrics for each segment.
WITH patient_stay_segments AS (
    SELECT 
        name,
        length_of_stay,
        billing_amount,
        CASE
            WHEN length_of_stay <= 7 THEN 'Short Stay (1-7 days)'
            WHEN length_of_stay BETWEEN 8 AND 21 THEN 'Medium Stay (8-21 days)'
            ELSE 'Extended Stay (>21 days)'
        END AS stay_segment
    FROM healthcare
)
SELECT 
    stay_segment,
    COUNT(*) AS number_of_patients,
    ROUND(AVG(billing_amount)::numeric, 2) AS avg_billing,
    ROUND(SUM(billing_amount)::numeric, 2) AS total_billing_revenue
FROM patient_stay_segments
GROUP BY stay_segment
ORDER BY number_of_patients DESC;


-- Q8. What are the top 2 most prescribed medications within each medical condition? (Window Function)
WITH medication_rankings AS (
    SELECT 
        medical_condition,
        medication,
        COUNT(*) AS total_prescriptions,
        ROW_NUMBER() OVER (
            PARTITION BY medical_condition 
            ORDER BY COUNT(*) DESC
        ) AS med_rank
    FROM healthcare
    GROUP BY medical_condition, medication
)
SELECT 
    med_rank,
    medical_condition,
    medication,
    total_prescriptions
FROM medication_rankings
WHERE med_rank <= 2
ORDER BY medical_condition, med_rank;


-- Q9. Are senior patients (age >= 60) more likely to have Abnormal test results compared to younger age cohorts?
SELECT 
    age_group,
    COUNT(*) AS total_patients,
    SUM(CASE WHEN test_results = 'Abnormal' THEN 1 ELSE 0 END) AS abnormal_test_count,
    ROUND(100.0 * SUM(CASE WHEN test_results = 'Abnormal' THEN 1 ELSE 0 END) / COUNT(*), 2) AS abnormal_rate_percentage
FROM healthcare
GROUP BY age_group
ORDER BY abnormal_rate_percentage DESC;


-- Q10. What is the total billing contribution and percentage share of each age group?
SELECT 
    age_group,
    COUNT(*) AS total_patients,
    ROUND(SUM(billing_amount)::numeric, 2) AS total_billing_amount,
    ROUND(100.0 * SUM(billing_amount) / (SELECT SUM(billing_amount) FROM healthcare), 2) AS billing_percentage_share
FROM healthcare
GROUP BY age_group
ORDER BY total_billing_amount DESC;
